insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('do-hods-a-eck', 'Do hods a Eck!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da hat es ein Eck!', '[{"kategorie": "wörtlich", "text": "\"Da stimmt was nicht!\"  2. \"Da gibt es ein Problem!\"  3. \"Da läuft was schief!\"  4. \"Da ist der Wurm drin!\""}]'::jsonb, 'a Eck haum'),
  ('do-mochds-a-eck', 'Do mochds a Eck!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da macht es ein Eck!', '[{"kategorie": "wörtlich", "text": "\"Da gibt es ein Problem!\"  2. \"Da stimmt was nicht!\"  3. \"Da läuft was schief!\"  4. \"Da ist der Wurm drin!\""}]'::jsonb, 'a Eck mochn'),
  ('im-eck-sei', 'im Eck sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'im Eck sein', '[{"kategorie": "wörtlich", "text": "\"am Boden sein\""}, {"kategorie": "", "text": "\"am Ende sein\""}, {"kategorie": "", "text": "\"nicht mehr weiterwissen\""}, {"kategorie": "", "text": "\"ohne Perspektive dastehen\""}, {"kategorie": "", "text": "\"in der Klemme sein\""}, {"kategorie": "", "text": "\"in einer Sackgasse sein\""}, {"kategorie": "", "text": "[[im Oasch sei]]"}]'::jsonb, 'Seit da Kindigung isa voi im Eck - innalich lääa und komplett ealedigt!'),
  ('seit-da-kindigung-isa-voi-im-eck-innalich-laeaea-und-komplett-ealedigt', 'Seit da Kindigung isa voi im Eck - innalich lääa und komplett ealedigt!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Seit der Kündigung ist er voll im Eck - innerlich leer und komplett erledigt!', '[{"kategorie": "wörtlich", "text": "\"Seit der Kündigung ist er völlig am Boden, innerlich leer und fertig mit sich selbst!\"  2. \"Seit dem Jobverlust ist er komplett am Ende, ausgebrannt und kraftlos!\"  3. \"Seit der Kündigung steht er ohne jede Perspektive da – innerlich tot, äußerlich nur noch Hülle!\""}]'::jsonb, 'im Eck sei'),
  ('iwas-eck', 'iwas Eck', '', '', '', 'Wiener Sprüche, die sitzen!', 'übers Eck', '[{"kategorie": "wörtlich", "text": "\"über die Ecke\""}, {"kategorie": "allg.", "text": "\"diagonal\" (sodass die Ecken aufeinanderliegen), \"von Ecke zu Ecke\", \"in der Diagonale\""}, {"kategorie": "fig.", "text": "uneins, zerstritten, verkracht, verfeindet"}]'::jsonb, 'Leegds de Seawiätn iwas Eck, des schaud eedla aus!'),
  ('leegds-de-seawiaetn-iwas-eck-des-schaud-eedla-aus', 'Leegds de Seawiätn iwas Eck, des schaud eedla aus!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Legt die Servietten übers Eck - das schaut edler aus!', '[{"kategorie": "wörtlich", "text": "\"Legt die Servietten diagonal, das wirkt eleganter!\"  2. \"Übers Eck gelegt sehen die Servietten einfach besser aus!\"  3. \"Legt die Servietten von Ecke zu Ecke – das gibt dem Tisch mehr Stil!\""}]'::jsonb, 'iwas Eck'),
  ('iwas-eck-mit-wem-sein', 'iwas Eck mit wem sein', '', '', '', 'Wiener Sprüche, die sitzen!', 'übers Eck mit jemandem sein', '[{"kategorie": "wörtlich", "text": "\"mit jemandem uneins sein\""}, {"kategorie": "", "text": "\"mit jemandem zerstritten sein\""}, {"kategorie": "", "text": "\"mit jemandem im Clinch liegen\""}, {"kategorie": "", "text": "\"mit jemandem auf Kriegsfuß stehen\""}, {"kategorie": "", "text": "[[mit wem iwas Kreiz sei]]"}]'::jsonb, ''),
  ('mit-mein-nochbarn-bin-i-iwas-eck-mia-reedn-schoo-drei-joa-nix-mea-mitanaund', 'Mit mein Nochbarn bin I iwas Eck - mia reedn schoo drei Joa nix mea mitanaund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit meinem Nachbarn bin ich übers Eck - wir reden schon drei Jahre nichts mehr miteinander!', '[{"kategorie": "wörtlich", "text": "\"Mit meinem Nachbarn bin ich zerstritten - seit drei Jahren herrscht zwischen uns jetzt schon Funkstille!\"  2. \"Mit meinem Nachbarn liege ich seit drei Jahren im Clinch - wir reden kein Wort mehr miteinander!\"  3. \"Mein Nachbar und ich sind total verkracht - seit drei Jahren tote Hose!\""}]'::jsonb, 'iwas Eck'),
  ('kuazes-eck', 'kuazes Eck', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'kurzes Eck', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"kurze Ecke\""}, {"kategorie": "", "text": "\"erster Pfosten\""}, {"kategorie": "", "text": "\"erste Stange\""}]'::jsonb, 'Ob kuazes oda launges Eck - des Runde muass ins Eckige!'),
  ('launges-eck', 'launges Eck', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'langes Eck', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"lange Ecke\""}, {"kategorie": "", "text": "\"zweiter Pfosten\""}, {"kategorie": "", "text": "\"zweite Stange\""}]'::jsonb, 'Ob kuazes oda launges Eck - des Runde muass ins Eckige!'),
  ('ob-kuazes-oda-launges-eck-des-runde-muass-ins-eckige', 'Ob kuazes oda launges Eck - des Runde muass ins Eckige!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ob kurzes oder langes Eck - das Runde muss ins Eckige!', '[{"kategorie": "wörtlich", "text": "\"Ob kurze oder lange Ecke - egal wohin, Hauptsache Tor!\"  2. \"Ob du den Ball in die kurze oder lange Ecke schießt, ist egal - solange der Ball im Netz landet!\"  3. \"Kurz oder lang, drin ist drin!\""}]'::jsonb, 'kuazes Eck'),
  ('bruada-ums-eck', 'Bruada ums Eck!', '', '', '', 'Echte Wiener Schmähperlen', 'Bruder ums Eck!', '[{"kategorie": "wörtlich, Ausruf der Überraschung oder der Bewunderung", "text": "\"Bruder, was geht denn hier ab?!\"  2. \"Ach du liebe Zeit!\"  3. \"Um Himmel willen!\""}, {"kategorie": "", "text": "\"Mann oh Mann!\"  5. \"Heiliger Bimbam!\"  6. [[I scheiß mia au!]]"}]'::jsonb, 'Bruada ums Eck! Amoi ned hiigschaud und schoo brennd de Hittn!'),
  ('bruada-ums-eck-amoi-ned-hiigschaud-und-schoo-brennd-de-hittn', 'Bruada ums Eck! Amoi ned hiigschaud und schoo brennd de Hittn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Bruder ums Eck! Einmal nicht hingeschaut, und schon brennt die Hütte!', '[{"kategorie": "wörtlich", "text": "\"Bruder, was geht denn hier ab?! Einmal nicht hingeschaut, und schon brennt die Hütte!\"  2. \"Ach du liebe Zeit! Einmal weggeguckt, und schon steht der Laden in Flammen!\"  3. \"Mann oh Mann! Da bin ich zwei Sekunden weg, und schon herrscht das totale Chaos!\""}]'::jsonb, 'Bruada ums Eck!'),
  ('wem-ums-eck-draan', 'wem ums Eck draan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden ums Eck drehen', '[{"kategorie": "wörtlich", "text": "\"jemanden um die Ecke drehen\""}, {"kategorie": "fig., Gaunerjargon", "text": "\"jemanden von der Bildfläche verschwinden lassen\""}, {"kategorie": "", "text": "jemanden aus dem Weg räumen\""}, {"kategorie": "allg.", "text": "\"jemanden ins Jenseits befördern\""}, {"kategorie": "", "text": "jemanden kaltmachen, töten, umbringen, ermorden, [[haamdraan]]"}]'::jsonb, 'wem haamdraan'),
  ('dea-draad-di-ums-eck-waunnsd-ned-zoist', 'Dea draad di ums Eck, waunnsd ned zoist!', '', '', '', 'Wiener Gaunersprache', 'Der dreht dich um die Ecke, wenn du nicht zahlst!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Der lässt dich von der Bildfläche verschwinden, wenn du nicht bezahlst!\"  2. \"Der knipst dir das Licht aus, wenn er das Geld nicht bekommt!\"  3. \"Der macht dich kalt, wenn er sein Geld nicht sieht!\""}]'::jsonb, 'wem ums Eck draan'),
  ('waunn-da-eiskostn-laeaea-is-rettn-da-zwaa-eckalkaas-de-wueade', 'Waunn da Eiskostn lääa is, rettn da zwaa Eckalkaas de Wüade!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn der Eiskasten leer ist, retten dir zwei Eckerlkas die Würde!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Kühlschrank leer ist, retten dir zwei Ecken Streeichkäse die Würde!\"  2. \"Ist der Kühlschrank leer, halten dich zwei Streichkäse-Ecken über Wasser!\"  3. \"Wo der Eisschrank nur noch Licht spendet, bringen zwei Käseecken die Ehre wieder zurück!\""}]'::jsonb, ''),
  ('i-woon-in-an-eckhaus-do-foad-ma-de-bim-fost-duachs-woonzimma', 'I woon in an Eckhaus - do foad ma de Bim fost duachs Woonzimma!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich wohne in einem Eckhaus - da fährt mir die Bim fast durchs Wohnzimmer!', '[{"kategorie": "wörtlich", "text": "\"Ich wohne in einem Mietshaus an der Straßenecke - da fährt mir die Tramway fast durchs Wohnzimmer!\"  2. \"Ich wohne in einem Eckmietshaus - die Bim schneidet die Kurve direkt durch mein Wohnzimmer!\"  3. \"Ich wohn'' in ''nem Eckhaus und hab'' die Straßenbahn direkt vor der Tür - ich könnt vom Wohnzimmer aus fast direkt einsteigen!\""}]'::jsonb, ''),
  ('um-a-eckhaus-mea', 'um a Eckhaus mea', '', '', '', 'Wiener Sprüche, die sitzen!', 'um ein Eckhaus mehr', '[{"kategorie": "wörtlich", "text": "\"um ein Vielfaches mehr\""}, {"kategorie": "", "text": "\"um Längen mehr\""}, {"kategorie": "", "text": "\"um Welten mehr\""}, {"kategorie": "", "text": "\"sehr viel mehr\", \"erheblich mehr\", \"bei Weitem mehr\""}]'::jsonb, 'In dera Bumsn zoist fiara Schnitzl um a Eckhaus mea!'),
  ('in-dera-bumsn-zoist-fiara-schnitzl-um-a-eckhaus-mea', 'In dera Bumsn zoist fiara Schnitzl um a Eckhaus mea!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'In dieser Bumsen zahlst du für ein Schnitzel um ein Eckhaus mehr!', '[{"kategorie": "wörtlich", "text": "\"In diesem Bumslokal kostet das Schnitzel um ein Vielfaches mehr!\"  2. \"In diesem unterirdischen Lokal verlangen sie für ein Schnitzel eine ganz andere Hausnummer!\"  3. \"In dieser Polterbude nehmen sie dir für ein Schnitzel viel mehr ab als anderswo!\""}]'::jsonb, 'um a Eckhaus mea'),
  ('an-rausch-wiara-eckhaus-haum', 'an Rausch wiara Eckhaus haum', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'einen Rausch wie ein Eckhaus haben', '[{"kategorie": "wörtlich", "text": "\"einen Vollrausch haben\""}, {"kategorie": "", "text": "[[blunzenfett sein]]"}, {"kategorie": "", "text": "[[fett wie die russische Erde sein]]"}, {"kategorie": "", "text": "[[in da Voifettn sei]]"}]'::jsonb, 'Gestan hob I an Rausch wiara Eckhaus ghobd - do is ma sogoa mei Oide liab vuakumma!'),
  ('gestan-hob-i-an-rausch-wiara-eckhaus-ghobd-do-is-ma-sogoa-mei-oide-liab-vuakumma', 'Gestan hob I an Rausch wiara Eckhaus ghobd - do is ma sogoa mei Oide liab vuakumma!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gestern hab ich einen Rausch wie ein Eckhaus gehabt - da ist mir sogar meine Alte lieb vorgekommen!', '[{"kategorie": "wörtlich", "text": "\"Gestern war ich fett wie die russische Erde - da war mir sogar meine Alte wieder sympathisch!\"  2. \"Gestern war ich voll wie ein Betonmischer – da hätt'' ich sogar meine Alte nochmals geheiratet!\"  3. \"Gestern war ich bis oben hin dicht - sogar meine Alte ist mir lieb und nett vorgekommen!\""}]'::jsonb, 'an Rausch wiara Eckhaus haum'),
  ('eckschdaa-haawara', 'Eckschdaa-Haawara', 'der', '', '', 'Echte Wiener Schmähperlen', 'Eckstein-Haberer', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Kumpel, der in der Justizanstalt Stein im Eck sitzt\" (Determinativkompositum aus \"Eckstein\"=\"Zellenecke in der [[Justizanstalt]] Stein\" und [[Haberer]]=\"Kumpel\")"}, {"kategorie": "Gaunersprache, scherzhaft für", "text": "\"Steingänger\", \"Stein-Veteran\", \"Dauergast in der Justizanstalt Stein\", \"Häfenbruder\", \"Gewohnheitsverbrecher\", \"Mehrfachvorbestrafter\", \"Häfenstammgast\""}]'::jsonb, 'Ia Ex is a Eckschdaa-Haawara - fuffzg Joa, davoo zwanzg im Hääfn!'),
  ('ia-ex-is-a-eckschdaa-haawara-fuffzg-joa-davoo-zwanzg-im-haeaefn', 'Ia Ex is a Eckschdaa-Haawara - fuffzg Joa, davoo zwanzg im Hääfn!', '', '', '', 'Wiener Gaunersprache', 'Ihr Ex ist ein Eckstein-Haberer - fünfzig Jahre, davon zwanzig im Häfen!', '[{"kategorie": "wörtlich", "text": "\"Ihr Ex ist Dauergast in der Justizanstalt [[Stein]] - fünfzig Jahre alt, davon zwanzig im Knast!\"  2. \"Ihr Ex ist ein alter Steingänger – fünfzig Jahre alt, davon zwanzig im Gefängnis!\"  3. \"Ihr Ex ist ein Stein-Veteran - hat fast die Hälfte seines Lebens im Gefängnis gesessen!\""}]'::jsonb, ''),
  ('friara-hoda-de-mentscha-gjoogd-heit-schiabda-de-eheschdaundslokomotiiv-braav-vua-sich-hea', 'Friara hoda de Mentscha gjoogd - heit schiabda de Eheschdaundslokomotiiv braav vua sich hea!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Früher hat er die Mentscher gejagt - heute schiebt er die Ehestandslokomotive brav vor sich her!', '[{"kategorie": "wörtlich", "text": "\"Früher hat er die jungen Mädels gejagt - heute schiebt er den Kinderwagen brav durch den Park!\"  2. \"Einst war er Frauenjäger - heute ist er familienbraver Kinderwagenschieber!\"  3. \"Früher ist er jedem Rock nachgejagt - heute ist er im Schlurfschritt mit Buggy unterwegs!\""}]'::jsonb, ''),
  ('des-bringd-jo-aeae-nix', 'Des bringd jo ää nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das bringt ja eh nichts!', '[{"kategorie": "wörtlich", "text": "\"Das bringt doch sowieso nichts!\"  2. \"Das ist ohnehin [[für]] die Katz!\"  3. \"Das ist ja eh komplett umsonst!\"  4. \"Das ist doch ohnedies [[fürn]] Arsch!\""}]'::jsonb, ''),
  ('aeae-schoo-wissn', 'ää schoo wissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eh schon wissen', '[{"kategorie": "wörtlich", "text": "\"wie jeder weiß\""}, {"kategorie": "", "text": "\"wie zu erwarten\""}, {"kategorie": "", "text": "\"wenig überraschend\""}, {"kategorie": "", "text": "\"wie absehbar\""}]'::jsonb, 'De bestn Plätz san wiida moi - ää schoo wissn - olle ausvakaufd!'),
  ('de-bestn-plaetz-san-wiida-moi-aeae-schoo-wissn-olle-ausvakaufd', 'De bestn Plätz san wiida moi - ää schoo wissn - olle ausvakaufd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die besten Plätze sind wieder mal - eh schon wissen - alle ausverkauft!', '[{"kategorie": "wörtlich", "text": "\"Die besten Plätze sind wieder mal - wenig überraschend - alle ausverkauft!\"  2. \"Wie zu erwarten, sind die besten Plätze schon wieder alle futsch!\"  3. \"Die besten Plätze sind - wie jeder weiß - schon alle weg!\""}]'::jsonb, 'ää schoo wissn'),
  ('aeae-schoo', 'ää schoo', '', '', '', 'Wiener Sprüche, die sitzen!', 'eh schon', '[{"kategorie": "wörtlich", "text": "\"ohnehin schon\""}, {"kategorie": "", "text": "\"sowieso schon\""}, {"kategorie": "", "text": "\"ohnedies bereits\""}, {"kategorie": "", "text": "\"sowieso schon längst\""}]'::jsonb, 'Do hob I ää scho gnua!'),
  ('do-hob-i-aeae-scho-gnua', 'Do hob I ää scho gnua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hab ich eh schon genug!', '[{"kategorie": "wörtlich", "text": "\"Da reicht''s mir sowieso schon!\"  2. \"Das reicht mir bis hierher!\"  3. \"Mehr davon brauche ich wirklich nicht!\"  4. \"Ich kann den Scheiß keinen Meter mehr ertragen!\""}]'::jsonb, 'ää schoo'),
  ('i-jo-aeae-jo-aa', 'I jo ää jo aa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich ja eh ja auch!', '[{"kategorie": "wörtlich, z.B. als Reaktion auf die Behauptung: \"Ich hab''s immer schon gewusst!\"", "text": "\"Ich ja ohnehin auch!\"  2. Ich ja sowieso auch!  3. Ich ja eh auch!"}]'::jsonb, ''),
  ('najo-aeae-aa-soo', 'Najo, ää aa soo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Naja, eh auch so!', '[{"kategorie": "wörtlich, als Antwort auf die Frage: \"Wie geht''s dir so?\"", "text": "\"Naja, es geht so!\"  2. \"Naja, mal so, mal so!\"  3. \"Naja, so lala!\"  4. \"Naja, nicht so schlecht, aber es könnte besser sein!\""}]'::jsonb, ''),
  ('i-hob-imma-a-eia-wuafbereid-im-haundschuufoch', 'I hob imma a Eia wuafbereid im Haundschuufoch!', '', '', '', 'Wiener Gaunersprache', 'Ich habe immer ein Eia wurfbereit im Handschuhfach!', '[{"kategorie": "wörtlich", "text": "\"Ich habe immer ein Spreng-Ei wurfbereit im Handschuhfach!\"  2. Ich fahr nie ohne Handgranate im Handschuhfach!  3. Bei mir im Handschuhfach liegt jederzeit eine entsicherte Handgranate bereit!"}]'::jsonb, ''),
  ('so-a-eia', 'So a Eia!', '', '', '', 'Wiener Sprüche, die sitzen!', 'So ein Eia!', '[{"kategorie": "wörtlich", "text": "\"So ein Ei!\"  2. So ein Dilettant!  3. Was für ein Stümper!  4. [[So]] ein Weh!"}]'::jsonb, ''),
  ('so-a-waeae', 'So a Wää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Weh!', '[{"kategorie": "wörtlich", "text": "\"So ein Stümper!\"  2. Was für ein Dilettant!  3. [[So]] a Eia!"}]'::jsonb, ''),
  ('des-hendl-hod-a-eia-gleegd', 'Des Hendl hod a Eia gleegd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Das Hendl hat ein Ei gelegt!', '[{"kategorie": "wörtlich", "text": "\"Die Henne hat ein Ei gelegt!\"  2. Das Huhn hat ein Ei gelegt!  3. Die Henne hat ein Ei ausgebrütet!"}]'::jsonb, ''),
  ('host-no-a-eia-fia-mi', 'Host no a Eia fia mi?', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Hast du noch ein Eia für mich?', '[{"kategorie": "wörtlich", "text": "\"Hast du noch ein Ei für mich?\"  2. Könntest du mir noch ein Ei geben?\"  3. Hast du vielleicht noch ein Ei für mich übrig?  4. Gibt’s noch ein Ei für mich?"}]'::jsonb, ''),
  ('heid-tua-i-meine-eia-huutschn', 'Heid tua i meine Eia huutschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Heute tue ich meine Eier hutschen!', '[{"kategorie": "wörtlich", "text": "\"Heute tu ich meine Eier schaukeln!\"  2. (scherzhaft für): \"Heute tu ich nichts als faulenzen!  3. Heute lasse ich meine Seele baumeln!"}]'::jsonb, 'seine Eia huutschn'),
  ('des-geed-ma-aufd-eia', 'Des geed ma aufd Eia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das geht mir auf die Eier!', '[{"kategorie": "scherzhaft für", "text": "Das geht mir auf den Sack!  2. Das geht mir richtig auf den [[Zeiger]]!  3. Das geht mir am Arsch!"}]'::jsonb, ''),
  ('wem-aufd-eia-schdeing', 'wem aufd Eia schdeing', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf die Eier steigen', '[{"kategorie": "wörtlich", "text": "\"jemandem den Arsch aufreißen\""}, {"kategorie": "", "text": "\"jemandem auf die Pelle rücken\""}, {"kategorie": "", "text": "\"jemanden die Hölle heiß machen\""}, {"kategorie": "", "text": "\"jemandem ständig im Nacken sitzen\""}]'::jsonb, 'wem in Oasch aufreissn'),
  ('nooch-da-sechsdn-bloodan-in-serie-is-uns-da-traeaena-uandlich-aufd-eia-gschdiing', 'Nooch da sechsdn Bloodan in Serie is uns da Trääna uandlich aufd Eia gschdiing!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach der sechsten Bladern in Serie ist uns der Trainer ordentlich auf die Eier gestiegen!', '[{"kategorie": "wörtlich", "text": "\"Nach der sechsten Niederlage in Serie ist uns der Trainer ordentlich auf die Eier gestiegen!\"  2. \"Nach sechs verlorenen Spielen hat uns der Trainer so richtig den Arsch aufgerissen!\"  3. \"Sechs Spiele, null Punkte - da ist der Trainer ausgeratstet und hat uns die Hölle heiß gemacht!\""}]'::jsonb, 'wem aufd Eia schdeing'),
  ('mit-dem-baungadn-hods-eam-a-uandlichs-eia-gleegd', 'Mit dem Baungadn hods eam a uandlichs Eia gleegd!', '', '', '', 'Grundwortschatz Wienerisch', 'Mit dem Bankerten hat sie ihm ein ordentliches Ei gelegt!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem unehelichen Kind hat sie ihm ein ordentliches Kuckucksei ins Nest gelegt!\"  2. \"Mit dem Kind hat sie ihm ein fettes Ei untergeschoben!\"  3. \"Mit dem unehelichen Kind hat sie ihm ein dickes Überraschungsei beschert - und er weiß nicht einmal, ob es wirklich von ihm ist!\""}]'::jsonb, 'wem a Eia leeng'),
  ('aufm-plotz-brauch-ma-kaane-eiataenza-sondan-schbueuela-mit-eia', 'Aufm Plotz brauch ma kaane Eiatänza, sondan Schbüüla mit Eia!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Auf dem Platz brauchen wir keine Eiertänzer, sondern Spieler mit Eier!', '[{"kategorie": "wörtlich", "text": "\"Auf dem Platz brauchen wir keine Zauderer, sondern Kerle mit Rückgrat!\"  2. \"Auf dem Spielfeld brauchen wir keine herumtänzelnden Weicheier, sondern Männer, die hinlangen!\"  3. \"Auf dem Platz haben Weicheier nichts verloren - da brauchern wir Männer mit richtigen Eiern in den Hosen!\""}]'::jsonb, ''),
  ('dea-eiagaenga-schoffds-ka-anzigs-moi-jo-oda-na-zum-soong', 'Dea Eiagänga schoffds ka anzigs Moi, ''Jo'' oda ''Na'' zum Soong!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Eiergänger schafft es kein einziges Mal, ''Ja'' oder ''Nein'' zu sagen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Eiertänzer schafft es kein einziges Mal, ''Ja'' oder ''Nein'' zu sagen!\"  2. \"Dieser Warmduscher tanzt um jedes Ja/Nein herum, ohne sich festzulegen!  3. Dieser Zauderer drückt sich um jede klare Aussage!  4. Dieser Weichei schafft es nie, mal klar Farbe zu bekennen!"}]'::jsonb, ''),
  ('fuassboireegl-numma-1-eiagoi-zoeoen-doppaed', 'Fuassboireegl Numma 1: Eiagoi zöön doppäd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Fußballregel Nummer 1: Eiergoals zählen doppelt!', '[{"kategorie": "wörtlich", "text": "\"Fußballregel Nummer 1: Eiertore zählen doppelt!\"  2. Fußballweisheit Nr. 1: Je peinlicher das Tor, desto wichtiger!  3. Stadionregel Nr. 1: Je lächerlicher der Treffer, desto lauter der Jubel!"}]'::jsonb, ''),
  ('wea-so-a-eiatiarl-kassiad-kaunn-glei-an-goatnzweag-ins-goi-schdoeoen', 'Wea so a Eiatiarl kassiad, kaunn glei an Goatnzweag ins Goi schdöön!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wer so ein Eiertor kassiert, kann gleich einen Gartenzwerg ins Tor stellen!', '[{"kategorie": "wörtlich", "text": "\"Wer so ein Kacktor kassiert, kann auch ’nen Gartenzwerg ins Tor stellen!\"  2. Wenn du so ein Eiergoal kassierst, bist du keine Nummer Eins – da bist du ’ne Lachnummer!  3. Was für ein Eiertor! Stell beim nächsten Mal eine Schaufensterpuppe ins Tor, die bewegt sich wenigstens nicht falsch!"}]'::jsonb, ''),
  ('seit-bei-de-austriana-a-schdeira-im-tiarl-schdeed-kriangs-a-jeeds-maetsch-a-schdeiragoi', 'Seit bei de Austriana a Schdeira im Tiarl schdeed, kriangs a jeeds Mätsch a Schdeiragoi!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Seit bei den Austrianern ein Steirer im Tor steht, kriegen sie jedes Match ein Steirergoal!', '[{"kategorie": "wörtlich", "text": "\"Seit bei der Mannschaft des SK Austria Wien ein Steirer im Tor steht, kassieren sie jedes Match ein Steirertor!\"  2. Seit bei der Mannschaft des SK Austria Wien ein Steirer im Tor steht, kassieren sie jedes Match einen haltbaren Treffer!  3. Seit Austria Wien mit einem Steirer im Tor spielt, häufen sich die leicht vermeidbaren Gegentore!"}]'::jsonb, ''),
