  ('den-muassd-min-richtign-schmaeae-pockn-daunn-frissda-da-aus-da-haund-und-meakds-ned-amoi', 'Den muassd min richtign Schmää pockn - daunn frissda da aus da Haund und meakds ned amoi!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Den musst du mit''m richtigen Schmäh packen - dann frisst er dir aus der Hand und merkt’s nicht einmal!', '[{"kategorie": "wörtlich", "text": "\"Den musst du charmant um den Finger wickeln - und schon läuft er dir nach wie ein Dackel!\"  2. Wenn du dem mit dem richtigen Spruch kommst, unterschreibt er dir alles, was du willst!  3. Den musst du mit viel Witz und Charme einfangen - und schon tanzt er nach deiner Pfeife!"}]'::jsonb, 'wem min Schmää pockn'),
  ('schmaeae-fian', 'Schmää fian', '', '', '', 'Wiener Sprüche, die sitzen!', 'Schmäh führen', '[{"kategorie": "wörtlich", "text": "\"mit Witz und Charme parlieren\""}, {"kategorie": "", "text": "\"Witze reißen\""}, {"kategorie": "", "text": "\"schlagfertige Bemerkungen machen\""}, {"kategorie": "", "text": "\"Sprüche klopfen\""}, {"kategorie": "", "text": "\"Pointen schleudern\""}, {"kategorie": "", "text": "\"Gags landen\""}]'::jsonb, ''),
  ('ea-hod-so-laung-schmaeae-gfiad-bis-eam-de-goschn-von-soeoewa-zuagfoin-is', 'Ea hod so laung Schmää gfiad, bis eam de Goschn von sööwa zuagfoin is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er hat so lange Schmäh geführt, bis ihm die Gosch''n von selber zugefallen ist!', '[{"kategorie": "wörtlich", "text": "\"Er hat so lange Witze gerissen, bis ihm die Klappe von selber zugefallen ist!\"  2. Er hat so lange Sprüche geklopft, bis ihm die Luft ausgegangen ist!  3. Er hat Pointen geschleudert, bis ihm schließlich die Munition ausgegangen ist!"}]'::jsonb, 'Schmää fian'),
  ('des-woa-doch-nua-schmaeae', 'Des woa doch nua Schmää!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das war doch nur Schmäh!', '[{"kategorie": "wörtlich", "text": "\"Das war doch nur Spaß!\"  2. \"Das war doch nicht ernst gemeint!\"  3. Nimm’s locker, war doch nur Blödelei!"}]'::jsonb, ''),
